/* Storelib Reviews managed in one place (round K5): the integration's own page with Overview, Reviews, Requests, Analytics and Settings. `review_imports`: one row per CSV import a store ran (the file's name, how many rows were imported and skipped, and a short report of each row's outcome), so the Reviews tab can list recent imports and undo one; server only. `reviews.import_id`: the import a review came from (null for every other review), so undoing an import deletes exactly its own rows, which are always unverified and never in a Storelib rating. `review_requests.delivered_at`, `opened_at` and `clicked_at`: when the mail provider said the review request was delivered, opened and its link pressed (the provider's webhook, matched by the request id the email carries), and `manual`: true when the store sent it by hand from the Requests tab. Indexes so the Reviews tab pages, filters and counts on the server: by rating, by where a review stands on the website, and the requests list by status. Changes no row. Needs part 134. Until it runs, the page shows reviews and requests as before, without import history, undo or open tracking. */
DO $do$ BEGIN IF to_regclass('public.reviews') IS NULL OR to_regclass('public.review_requests') IS NULL THEN RAISE NOTICE 'reviews manage: run part 52 and part 134 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.review_imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, file_name text CHECK (file_name IS NULL OR char_length(file_name) <= 200), imported integer NOT NULL DEFAULT 0 CHECK (imported >= 0), skipped integer NOT NULL DEFAULT 0 CHECK (skipped >= 0), report jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(report) = 'array' AND pg_column_size(report) < 262144), undone_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS review_imports_creator ON public.review_imports (creator_id, created_at DESC); ALTER TABLE public.review_imports ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.review_imports FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.review_imports TO service_role; END $do$;
DO $do$ BEGIN IF to_regclass('public.review_imports') IS NULL THEN RETURN; END IF; ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_id uuid REFERENCES public.review_imports(id) ON DELETE SET NULL; GRANT SELECT (import_id) ON public.reviews TO anon, authenticated; CREATE INDEX IF NOT EXISTS reviews_import ON public.reviews (import_id) WHERE import_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.reviews') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS reviews_creator_rating ON public.reviews (creator_id, rating, created_at DESC); IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'reviews' AND column_name = 'site_status') THEN CREATE INDEX IF NOT EXISTS reviews_creator_site ON public.reviews (creator_id, site_status, status, created_at DESC); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.review_requests') IS NULL THEN RETURN; END IF; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS delivered_at timestamptz; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS opened_at timestamptz; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS clicked_at timestamptz; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS manual boolean NOT NULL DEFAULT false; CREATE INDEX IF NOT EXISTS review_requests_creator_status ON public.review_requests (creator_id, status, created_at DESC); END $do$;
notify pgrst, 'reload schema';
